public AttributedList<Local> list(final String path, final Filter<String> filter) throws AccessDeniedException {
  final AttributedList<Local> children = new AttributedList<>();
  try (DirectoryStream<Path> stream = Files.newDirectoryStream(Paths.get(path), new DirectoryStream.Filter<Path>() {
    @Override
    public boolean accept(final Path entry) {
      if (null == entry.getFileName()) {
        return false;
      }
      return filter.accept(entry.getFileName().toString());
    }
  })) {
    for (Path entry : stream) {
      try {
        children.add(LocalFactory.get(entry.toString()));
      } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException | NullPointerException e) {
        throw new RuntimeException("Failed to add entry to children list", e);
      }
    }
  } catch (IOException e) {
    throw new LocalAccessDeniedException(MessageFormat.format(LocaleFactory.localizedString("Listing directory {0} failed", "Error"), this.getName()), e);
  } catch (FileSystemNotFoundException | SecurityException | IllegalArgumentException e) {
    throw new RuntimeException("Failed to access directory", e);
  }
  return children;
}
